INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca42-787f-a014-71d87a66447c'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A town’s population increases from 240,000 to 264,000 over one year. Find the percentage increase.', '10%', 'Increase = 264,000 - 240,000 = 24,000. Percentage increase = (24,000 / 240,000) × 100% = 10%.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.450Z'::timestamptz, '2026-08-15T07:50:40.450Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca51-7363-a8ab-b4fdd480ec1c'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A quantity p is directly proportional to q³. If q increases by 50%, find the percentage increase in p.', '237.5%', 'New q = 1.5q. New p = (1.5)³ p = 3.375 p. Percentage increase = (3.375 - 1) × 100% = 237.5%.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.465Z'::timestamptz, '2026-08-15T07:50:40.465Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca5a-7bf8-a767-fc94431569b2'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'A grass plant grows 85 picometres in 2 milliseconds. Estimate how far it grows in 1 second, giving the answer in metres in standard form.', '4.25 × 10⁻⁸ m', 'Growth in 1 s (1000 ms) = 85 × (1000 / 2) = 42,500 pm. In metres: 42,500 × 10⁻¹² = 4.25 × 10⁻⁸ m.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.474Z'::timestamptz, '2026-08-15T07:50:40.474Z'::timestamptz) ON CONFLICT (id) DO NOTHING;